function PTTM_TmLevel()
	if GetPlayerExtLevel then
		local v = GetPlayerExtLevel()
		if v and v > 0 then return v end
	end
	return GetLevel()
end

function PTTM_NoteId()
	local pt = GetPlayerType()
	if pt == nil or pt < 0 or pt > 2 then pt = 0 end
	return 86 + pt
end

function PTTM_Note(step)
	TaskNote(PTTM_NoteId(), step)
end

function PTTM_Phe()
	return GetTask(PTTM_T_PHE)
end

function PTTM_PheName()
	if PTTM_Phe() == 2 then return "Ma giíi" end
	if PTTM_Phe() == 1 then return "Tiªn giíi" end
	return "ch­a chän phe"
end

function PTTM_Today6()
	local d = 0
	if date then
		d = tonumber(date("%Y%m%d"))
	elseif GetLocalDate then
		local s = GetLocalDate("%Y%m%d")
		if s then d = tonumber(s) end
	end
	if d == nil or d <= 0 then d = floor(SystemTime() / 86400) end
	return mod(d, 1000000)
end

function PTTM_Reward(exp, cash)
	if exp and exp > 0 then AddOwnExp(exp) end
	if cash and cash > 0 then Earn(cash) end
	Msg2Player(format("NhËn ®­îc <color=yellow>%d<color> kinh nghiÖm vµ <color=yellow>%d<color> l­îng.", exp or 0, cash or 0))
end

function PTTM_FreeCells()
	if CalcFreeItemCellCount then
		local n = CalcFreeItemCellCount()
		if n then return n end
	end
	return 99
end

function PTTM_GoCamp()
	local p = PTTM_POS_TIEN
	if PTTM_Phe() == 2 then p = PTTM_POS_MA end
	NewWorld(PTTM_MAP, p[1], p[2])
	if SetFightState then SetFightState(1) end
end

-- quest summon beside the player (Linh Xa, Phong Thu Son Hon): owner = player id, timeout = secs
function PTTM_Summon(tpl, lv, name, kind, secs)
	local m, x, y = GetWorldPos()
	if m ~= PTTM_MAP then return 0 end
	local sw = SubWorldID2Idx(PTTM_MAP)
	if sw == nil or sw < 0 then return 0 end
	local ni = AddNpc(tpl, lv, sw, (x + 3) * 32, (y + 3) * 32, 1)
	if ni == nil or ni <= 0 then ni = AddNpc(tpl, lv, sw, x * 32, y * 32, 1) end
	if ni == nil or ni <= 0 then return 0 end
	SetNpcName(ni, name)
	SetNpcScript(ni, PTTM_MOB_SCRIPT)
	SetNpcParam(ni, 0, GetPlayerID())
	SetNpcParam(ni, 1, kind)
	SetNpcTimeout(ni, secs * 18)
	SetTask(PTTM_T_SUMMON, ni)
	return ni
end

function PTTM_SummonAlive(kind)
	local ni = GetTask(PTTM_T_SUMMON)
	if ni > 0 and GetNpcParam(ni, 1) == kind and GetNpcParam(ni, 0) == GetPlayerID() then return ni end
	return 0
end

